from app.cart_total import calc_total
from decimal import Decimal


def test_calc_total_empty():
    assert calc_total([]) == '0.00'

def test_calc_total_single_item():
    items = [{'price': '10.50', 'qty': 2}]
    assert calc_total(items) == '21.00'

def test_calc_total_multiple_items():
    items = [
        {'price': '10.50', 'qty': 2},
        {'price': '2.75', 'qty': 3}
    ]
    assert calc_total(items) == '28.75'

def test_calc_total_invalid_price_type():
    items = [{'price': 10.50, 'qty': 2}]
    try:
        calc_total(items)
    except ValueError as e:
        assert str(e) == 'Invalid price or quantity type.'

def test_calc_total_invalid_qty_type():
    items = [{'price': '10.50', 'qty': True}]
    try:
        calc_total(items)
    except ValueError as e:
        assert str(e) == 'Invalid price or quantity type.'

def test_calc_total_negative_price():
    items = [{'price': '-10.50', 'qty': 2}]
    try:
        calc_total(items)
    except ValueError as e:
        assert str(e) == 'Price must be a nonnegative finite decimal string.'

def test_calc_total_infinite_price():
    items = [{'price': 'Infinity', 'qty': 2}]
    try:
        calc_total(items)
    except ValueError as e:
        assert str(e) == 'Price must be a nonnegative finite decimal string.'

def test_calc_total_negative_quantity():
    items = [{'price': '10.50', 'qty': -2}]
    try:
        calc_total(items)
    except ValueError as e:
        assert str(e) == 'Quantity must be a nonnegative integer.'

